import {minerOutfitKey} from './miner-outfit.js';
const loader=document.getElementById('entryLoading'),phase=document.getElementById('entryLoadingPhase'),retry=document.getElementById('entryRetry'),bar=document.getElementById('entryProgress'),amount=document.getElementById('entryPercent'),runner=document.getElementById('entryRunner');
let progress=0,frame=0;const sheet=new Image();let outfit='hardhat-blue';try{outfit=minerOutfitKey(JSON.parse(localStorage.getItem('gemventure-save-v2')||'null'));}catch{}sheet.src='./assets/miner-wardrobe-v5/'+outfit+'/cave-run.png';
function animate(t){if(loader.hidden){frame=0;return;}if(sheet.complete&&sheet.naturalWidth){const c=runner.getContext('2d'),columns=sheet.naturalWidth/128,index=matchMedia('(prefers-reduced-motion: reduce)').matches?0:Math.floor(t/20)%32;c.clearRect(0,0,128,128);c.imageSmoothingEnabled=true;c.drawImage(sheet,(index%columns)*128,3*128,128,128,0,0,128,128);}frame=requestAnimationFrame(animate);}
export function entryLoading(value=0){progress=Math.max(progress,Math.min(100,Number(value)||0));document.getElementById('menuHost').inert=true;phase.hidden=true;retry.hidden=true;loader.hidden=false;loader.setAttribute('aria-busy','true');bar.style.setProperty('--progress',progress+'%');bar.setAttribute('aria-valuenow',progress);amount.textContent=progress+'%';if(!frame)frame=requestAnimationFrame(animate);}
export function entryLoaded(){document.getElementById('menuHost').inert=false;loader.hidden=true;loader.removeAttribute('aria-busy');if(frame)cancelAnimationFrame(frame);frame=0;}
export function entryFailed(){phase.hidden=false;phase.textContent='Não foi possível abrir o jogo. Tente novamente.';retry.hidden=false;loader.hidden=false;loader.removeAttribute('aria-busy');if(frame)cancelAnimationFrame(frame);frame=0;retry.focus();}
